#!/usr/bin/env python3
"""Generate dx7_gen.c: COM vtables for IDirectDraw7 / IDirectDrawSurface7 / IDirect3D7 / IDirect3DDevice7.
Every slot is a stdcall stub with the right number of argument bytes (so a stub can never unbalance the stack); real methods are in dx7.c and override by name."""
DD=[('QueryInterface',2),('AddRef',0),('Release',0),('Compact',0),('CreateClipper',3),('CreatePalette',4),('CreateSurface',3),('DuplicateSurface',2),('EnumDisplayModes',4),('EnumSurfaces',4),('FlipToGDISurface',0),('GetCaps',2),('GetDisplayMode',1),('GetFourCCCodes',2),('GetGDISurface',1),('GetMonitorFrequency',1),('GetScanLine',1),('GetVerticalBlankStatus',1),('Initialize',1),('RestoreDisplayMode',0),('SetCooperativeLevel',2),('SetDisplayMode',5),('WaitForVerticalBlank',2),('GetAvailableVidMem',3),('GetSurfaceFromDC',2),('RestoreAllSurfaces',0),('TestCooperativeLevel',0),('GetDeviceIdentifier',2),('StartModeTest',3),('EvaluateMode',2)]
SF=[('QueryInterface',2),('AddRef',0),('Release',0),('AddAttachedSurface',1),('AddOverlayDirtyRect',1),('Blt',5),('BltBatch',3),('BltFast',5),('DeleteAttachedSurface',2),('EnumAttachedSurfaces',2),('EnumOverlayZOrders',3),('Flip',2),('GetAttachedSurface',2),('GetBltStatus',1),('GetCaps',1),('GetClipper',1),('GetColorKey',2),('GetDC',1),('GetFlipStatus',1),('GetOverlayPosition',2),('GetPalette',1),('GetPixelFormat',1),('GetSurfaceDesc',1),('Initialize',2),('IsLost',0),('Lock',4),('ReleaseDC',1),('Restore',0),('SetClipper',1),('SetColorKey',2),('SetOverlayPosition',2),('SetPalette',1),('Unlock',1),('UpdateOverlay',5),('UpdateOverlayDisplay',1),('UpdateOverlayZOrder',2),('GetDDInterface',1),('PageLock',1),('PageUnlock',1),('SetSurfaceDesc',2),('SetPrivateData',4),('GetPrivateData',3),('FreePrivateData',1),('GetUniquenessValue',1),('ChangeUniquenessValue',0),('SetPriority',1),('GetPriority',1),('SetLOD',1),('GetLOD',1)]
D3=[('QueryInterface',2),('AddRef',0),('Release',0),('EnumDevices',2),('CreateDevice',3),('CreateVertexBuffer',3),('EnumZBufferFormats',3),('EvictManagedTextures',0)]
DV=[('QueryInterface',2),('AddRef',0),('Release',0),('GetCaps',1),('EnumTextureFormats',2),('BeginScene',0),('EndScene',0),('GetDirect3D',1),('SetRenderTarget',2),('GetRenderTarget',1),('Clear',5),('SetTransform',2),('GetTransform',2),('SetViewport',1),('MultiplyTransform',2),('GetViewport',1),('SetMaterial',1),('GetMaterial',1),('SetLight',2),('GetLight',2),('SetRenderState',2),('GetRenderState',2),('BeginStateBlock',0),('EndStateBlock',1),('PreLoad',1),('DrawPrimitive',5),('DrawIndexedPrimitive',7),('SetClipStatus',1),('GetClipStatus',1),('DrawPrimitiveStrided',5),('DrawIndexedPrimitiveStrided',7),('DrawPrimitiveVB',5),('DrawIndexedPrimitiveVB',7),('ComputeSphereVisibility',4),('GetTexture',2),('SetTexture',2),('GetTextureStageState',3),('SetTextureStageState',3),('ValidateDevice',1),('ApplyStateBlock',1),('CaptureStateBlock',1),('DeleteStateBlock',1),('CreateStateBlock',2),('Load',5),('LightEnable',2),('GetLightEnable',2),('SetClipPlane',2),('GetClipPlane',2),('GetInfo',3)]
o=['/* generated by gen_dx7.py */','#include "win.h"','void lt_dx_unimpl(const char *what);']
tabs=[('dd',DD),('sf',SF),('d3',D3),('dv',DV)]
for pre,t in tabs:
    for name,n in t:
        args=''.join(',uint32_t a%d'%i for i in range(n))
        o.append('int WINAPI %s_stub_%s(void *t%s){ lt_dx_unimpl("%s::%s"); return 0x80004001; }'%(pre,name,args,pre.upper(),name))
        o.append('int WINAPI %s_%s(void *t%s) __attribute__((weak,alias("%s_stub_%s")));'%(pre,name,args,pre,name))
    o.append('void *%s_vtbl[]={'%pre+','.join('(void*)%s_%s'%(pre,nm) for nm,_ in t)+'};')
open('dx7_gen.c','w').write('\n'.join(o)+'\n'); print('slots',sum(len(t) for _,t in tabs))
